import{_ as s,c as n,o as e,a0 as t}from"./chunks/framework.CAcMrZkh.js";const k=JSON.parse('{"title":"部署总览","description":"BearPlan 部署总览：后端、前端、移动端三条独立部署链路，后端 Docker aspnet 容器、前端 nginx 静态托管、移动端各平台分发，三端共享同一套后端 API。","frontmatter":{"title":"部署总览","description":"BearPlan 部署总览：后端、前端、移动端三条独立部署链路，后端 Docker aspnet 容器、前端 nginx 静态托管、移动端各平台分发，三端共享同一套后端 API。"},"headers":[],"relativePath":"bearplan/deploy.md","filePath":"bearplan/deploy.md"}'),i={name:"bearplan/deploy.md"};function l(p,a,r,d,o,h){return e(),n("div",null,a[0]||(a[0]=[t(`<h1 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h1><p>BearPlan 是前后端分离的多端架构，部署分三条独立链路，各自构建产物、各自运行环境，互不耦合。</p><h2 id="三端概览" tabindex="-1">三端概览 <a class="header-anchor" href="#三端概览" aria-label="Permalink to &quot;三端概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端</th><th>项目</th><th>构建产物</th><th>运行环境</th></tr></thead><tbody><tr><td><strong>后端</strong></td><td><code>BearPlan.Api</code></td><td>.NET 程序文件（DLL + 配置 + 静态资源）</td><td>Docker 容器（aspnet 镜像）</td></tr><tr><td><strong>前端</strong></td><td><code>BearPlan.Admin</code></td><td>静态文件（HTML/CSS/JS）</td><td>Docker 容器（nginx 镜像）或任意静态服务器</td></tr><tr><td><strong>移动端</strong></td><td>Uni-App 工程</td><td>各平台安装包（H5/小程序/App）</td><td>各平台对应分发渠道</td></tr></tbody></table><h2 id="部署链路" tabindex="-1">部署链路 <a class="header-anchor" href="#部署链路" aria-label="Permalink to &quot;部署链路&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后端 BearPlan.Api              前端 BearPlan.Admin           移动端</span></span>
<span class="line"><span>─────────────────              ────────────────────          ──────────────────</span></span>
<span class="line"><span>dotnet publish                 pnpm build                    各平台构建</span></span>
<span class="line"><span>     │                              │                              │</span></span>
<span class="line"><span>产物上传服务器                       dist 产物                        安装包</span></span>
<span class="line"><span>     │                              │                              │</span></span>
<span class="line"><span>docker run (aspnet)            docker run (nginx) / 静态托管    分发到各平台</span></span>
<span class="line"><span>     │                              │                              │</span></span>
<span class="line"><span>     └──── 提供 API ────────────────┘                              │</span></span>
<span class="line"><span>                   │                                               │</span></span>
<span class="line"><span>                   └───────── 调用 API ────────────────────────────┘</span></span></code></pre></div><p>三端共享同一套后端 API，部署相互独立：后端先就绪，前端和移动端各自指向后端地址即可。</p><h2 id="选择部署方式" tabindex="-1">选择部署方式 <a class="header-anchor" href="#选择部署方式" aria-label="Permalink to &quot;选择部署方式&quot;">​</a></h2><ul><li><strong><a href="/bearplan/deploy-api.html">后端部署（BearPlan.Api）</a></strong> —— 本机发布 + 上传产物 + Docker 运行，生产可用方案。</li><li><strong><a href="/bearplan/deploy-admin.html">前端部署（BearPlan.Admin）</a></strong> —— 多阶段构建打包进 nginx，或托管到 CDN。</li><li><strong><a href="/bearplan/deploy-mobile.html">移动端部署</a></strong> —— Uni-App 多端构建与分发。</li></ul><h2 id="通用前提" tabindex="-1">通用前提 <a class="header-anchor" href="#通用前提" aria-label="Permalink to &quot;通用前提&quot;">​</a></h2><p>无论部署哪一端，服务器都需要安装 Docker：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ubuntu / Debian</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://get.docker.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span></code></pre></div><p>如果后端依赖宿主机上的 MySQL / Redis 等中间件，还需配置防火墙放行 docker 网段，详见博客 <a href="/blog/deploy/docker-firewall-allow-subnet.html">Docker 被防火墙拦截</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>从 <a href="/bearplan/deploy-api.html">后端部署</a> 开始，后端是前后端通信的基座，通常最先部署。</p>`,15)]))}const b=s(i,[["render",l]]);export{k as __pageData,b as default};
